type SubscriptionHandler struct{service *services.SubscriptionService};func NewSubscriptionHandler(s *services.SubscriptionService)*SubscriptionHandler{return &SubscriptionHandler{s}};func subUser(c *gin.Context)(primitive.ObjectID,bool){v,ok:=c.Get("userID");if !ok{return primitive.NilObjectID,false};id,e:=primitive.ObjectIDFromHex(v.(string));return id,e==nil};func subID(c *gin.Context)(primitive.ObjectID,bool){x,e:=primitive.ObjectIDFromHex(c.Param("id"));return x,e==nil}
func(h *SubscriptionHandler) List(c *gin.Context){u,ok:=subUser(c);if !ok{utils.Failure(c,401,"unauthorized",nil);return};p,_:=strconv.Atoi(c.DefaultQuery("page","1"));l,_:=strconv.Atoi(c.DefaultQuery("limit","20"));r,e:=h.service.List(c,u,repositories.SubscriptionQuery{Page:p,Limit:l,Search:c.Query("search"),Status:c.Query("status")});if e!=nil{utils.Failure(c,400,e.Error(),nil);return};c.JSON(200,gin.H{"success":true,"data":r.Items,"pagination":r})};func(h *SubscriptionHandler) Summary(c *gin.Context){u,ok:=subUser(c);if !ok{utils.Failure(c,401,"unauthorized",nil);return};r,e:=h.service.Summary(c,u);if e!=nil{utils.Failure(c,500,"unable to load subscription summary",nil);return};utils.Success(c,200,"Subscription summary retrieved.",r)}
func(h *SubscriptionHandler) Create(c *gin.Context){u,ok:=subUser(c);if !ok{utils.Failure(c,401,"unauthorized",nil);return};var x services.SubscriptionInput;if c.ShouldBindJSON(&x)!=nil{utils.Failure(c,400,"invalid request body",nil);return};r,e:=h.service.Create(c,u,x);if e!=nil{code:=400;if e==mongo.ErrNoDocuments{code=404};utils.Failure(c,code,e.Error(),nil);return};utils.Success(c,201,"Subscription created.",r)};func(h *SubscriptionHandler) Get(c *gin.Context){u,ok:=subUser(c);id,v:=subID(c);if !ok{utils.Failure(c,401,"unauthorized",nil);return};if !v{utils.Failure(c,400,"invalid subscription id",nil);return};r,e:=h.service.Get(c,u,id);if e!=nil||r==nil{utils.Failure(c,404,"subscription not found",nil);return};utils.Success(c,200,"Subscription retrieved.",r)};func(h *SubscriptionHandler) Update(c *gin.Context){u,ok:=subUser(c);id,v:=subID(c);if !ok||!v{utils.Failure(c,400,"invalid subscription request",nil);return};var x services.SubscriptionInput;if c.ShouldBindJSON(&x)!=nil{utils.Failure(c,400,"invalid request body",nil);return};r,e:=h.service.Update(c,u,id,x);if e==mongo.ErrNoDocuments||r==nil{utils.Failure(c,404,"subscription not found",nil);return};if e!=nil{utils.Failure(c,400,e.Error(),nil);return};utils.Success(c,200,"Subscription updated.",r)};func(h *SubscriptionHandler) Cancel(c *gin.Context){u,ok:=subUser(c);id,v:=subID(c);if !ok||!v{utils.Failure(c,400,"invalid subscription request",nil);return};if e:=h.service.Cancel(c,u,id);e!=nil{utils.Failure(c,404,"subscription not found",nil);return};utils.Success(c,200,"Subscription cancelled.",nil)}
